namespace sv_a77db295dc0c4870955b00ee49ae992b.Services;

/// <summary>
/// Stub implementation of IChatService for development/demo purposes.
/// Replace with a real implementation backed by a database or API.
/// </summary>
public class StubChatService : IChatService
{
    private readonly List<Channel> _channels =
    [
        new(1, "general", "General discussion for the team", 3),
        new(2, "engineering", "Engineering updates and technical discussions", 0),
        new(3, "random", "Off-topic and fun stuff", 1),
        new(4, "announcements", "Company-wide announcements", 5),
    ];

    private readonly List<Message> _messages =
    [
        new(1, 1, "Alice", "Hey everyone! Welcome to the new chat platform.", DateTime.UtcNow.AddHours(-2), null, [new("👍", ["Bob", "Charlie"]), new("🎉", ["Diana"])]),
        new(2, 1, "Bob", "Looks great! Love the new design.", DateTime.UtcNow.AddHours(-1.5), null, [new("❤️", ["Alice"])]),
        new(3, 1, "Charlie", "Are we migrating all channels over?", DateTime.UtcNow.AddMinutes(-45), null, []),
        new(4, 1, "Alice", "Yes, we plan to migrate everything by end of week.", DateTime.UtcNow.AddMinutes(-30), 3, [new("👍", ["Charlie"])]),
        new(5, 1, "Diana", "Can't wait to try the thread feature!", DateTime.UtcNow.AddMinutes(-10), null, []),
        new(6, 1, "Bob", "Same here, threads will be super useful for longer discussions.", DateTime.UtcNow.AddMinutes(-5), 5, []),
        new(7, 2, "Charlie", "Deployed v2.1 to staging. Please review.", DateTime.UtcNow.AddHours(-3), null, [new("👀", ["Alice", "Bob"])]),
        new(8, 2, "Alice", "Running tests now, will report back.", DateTime.UtcNow.AddHours(-2.5), 7, []),
    ];

    private int _nextMessageId = 9;

    public Task<List<Channel>> GetChannelsAsync() =>
        Task.FromResult(_channels.ToList());

    public Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take) =>
        Task.FromResult(
            _messages
                .Where(m => m.ChannelId == channelId && m.ReplyToId == null)
                .OrderBy(m => m.SentAt)
                .Skip(skip)
                .Take(take)
                .ToList());

    public Task<Message> SendMessageAsync(int channelId, string content, int? replyToId)
    {
        var message = new Message(_nextMessageId++, channelId, "You", content, DateTime.UtcNow, replyToId, []);
        _messages.Add(message);
        return Task.FromResult(message);
    }

    public Task<List<Message>> GetThreadAsync(int rootMessageId) =>
        Task.FromResult(
            _messages
                .Where(m => m.ReplyToId == rootMessageId)
                .OrderBy(m => m.SentAt)
                .ToList());

    public Task AddReactionAsync(int messageId, string emoji)
    {
        var msg = _messages.FirstOrDefault(m => m.Id == messageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing is not null)
            {
                if (!existing.Users.Contains("You"))
                    existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(emoji, ["You"]));
            }
        }
        return Task.CompletedTask;
    }

    public Task MarkChannelReadAsync(int channelId)
    {
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
        return Task.CompletedTask;
    }
}

